import { useTheme } from "@emotion/react";
import { Theme as TexturaTheme } from "@types";

import defaultTheme from "../bundled-themes/default";

declare module "@emotion/react" {
  // eslint-disable-next-line @typescript-eslint/no-empty-object-type
  interface Theme extends TexturaTheme {}
}

export const useTexturaTheme = (): TexturaTheme => {
  const theme = useTheme();

  if (Object.keys(theme).length === 0) {
    return defaultTheme;
  } else {
    return theme;
  }
};

export default useTexturaTheme;
